"""Independent query-alignment recurrence and manual BPTT, synthetic audit only."""
from __future__ import annotations
import json,math
from hashlib import sha256
from pathlib import Path
import numpy as np

def all_spans(documents):
    return [(window,left,right) for window,doc in enumerate(documents) for left in range(len(doc)) for right in range(left+1,len(doc)+1)]

def lse(values):
    maximum=float(np.max(values))
    return maximum+math.log(math.fsum(math.exp(float(v)-maximum) for v in values))

def forward(p,query,documents,spans,bypass=False):
    hidden=len(p['b']);scale=math.sqrt(hidden);query_states=[];query_trace=[];prev=np.zeros(hidden)
    for vector in query:
        x=np.r_[vector,1.,0.];r=p['W']@x+p['b']
        activation=np.tanh(r if bypass else r+p['U']@prev)
        current=activation if bypass else .5*prev+.5*activation
        query_trace.append((x,prev,activation));query_states.append(current);prev=current
    u=np.asarray(query_states).reshape(-1,hidden)
    aligned=(p['A']@u.T) if len(u) else np.zeros((hidden,0))
    states=[];traces=[]
    for document in documents:
        prev=u[-1].copy() if len(u) and not bypass else np.zeros(hidden)
        h=[];trace=[]
        for vector in document:
            x=np.r_[vector,0.,1.];r=p['W']@x+p['b']
            if len(u):
                logits=(r@aligned)/scale;exp=np.exp(logits-logits.max());alpha=exp/exp.sum();context=alpha@u
            else:alpha=np.zeros(0);context=np.zeros(hidden)
            activation=np.tanh(r+p['V']@context+(p['U']@prev if not bypass else 0))
            current=activation if bypass else .5*prev+.5*activation
            trace.append((x,r,prev,alpha,context,activation));h.append(current);prev=current
        states.append(np.asarray(h).reshape(-1,hidden));traces.append(trace)
    scores=np.array([p['span'][0]@states[w][a]+p['span'][1]@states[w][b-1]+p['span'][2]@states[w][a:b].mean(0) for w,a,b in spans])
    count=sum(map(len,documents));pooled=sum((h.sum(0) for h in states),np.zeros(hidden))/max(1,count)
    z=float(p['stop']@pooled+p['stop_bias'][0]);sigmoid=1/(1+math.exp(-z)) if z>=0 else math.exp(z)/(1+math.exp(z))
    return dict(scores=scores,stop_logit=z,p_stop=sigmoid,pooled=pooled,states=states,traces=traces,query_states=u,query_trace=query_trace)

def objective_and_gradient(p,query,documents,spans,gold,bypass=False,fixed_bypass_gradient=True):
    out=forward(p,query,documents,spans,bypass);z=out['stop_logit'];target=int(gold is None)
    gate=max(z,0)+math.log1p(math.exp(-abs(z)))-target*z;span_loss=0.;g={k:np.zeros_like(v) for k,v in p.items()}
    dz=out['p_stop']-target;g['stop']=dz*out['pooled'];g['stop_bias'][0]=dz
    count=sum(map(len,documents));direct=[np.tile(dz*p['stop']/max(1,count),(len(doc),1)) for doc in documents]
    if gold is not None:
        normal=lse(out['scores']);selected=lse(out['scores'][list(gold)]);span_loss=normal-selected
        coefficients=np.exp(out['scores']-normal);coefficients[list(gold)]-=np.exp(out['scores'][list(gold)]-selected)
        for coefficient,(w,a,b) in zip(coefficients,spans,strict=True):
            h=out['states'][w]
            g['span'][0]+=coefficient*h[a];g['span'][1]+=coefficient*h[b-1];g['span'][2]+=coefficient*h[a:b].mean(0)
            direct[w][a]+=coefficient*p['span'][0];direct[w][b-1]+=coefficient*p['span'][1];direct[w][a:b]+=coefficient*p['span'][2]/(b-a)
    u=out['query_states'];du=np.zeros_like(u);hidden=len(p['b']);scale=math.sqrt(hidden)
    for trace,dh in zip(out['traces'],direct,strict=True):
        carry=np.zeros(hidden)
        for t in range(len(trace)-1,-1,-1):
            x,r,previous,alpha,context,activation=trace[t]
            adjoint=dh[t]+(carry if not bypass else 0)
            da=(1 if bypass else .5)*adjoint*(1-activation*activation)
            g['V']+=np.outer(da,context);dc=p['V'].T@da;dr=da.copy()
            if len(u):
                dalpha=u@dc;ds=alpha*(dalpha-float(alpha@dalpha));weighted_query=ds@u
                g['A']+=np.outer(r,weighted_query)/scale
                dr+=(p['A']@weighted_query)/scale
                du+=np.outer(alpha,dc)+np.outer(ds,p['A'].T@r)/scale
            g['W']+=np.outer(dr,x);g['b']+=dr
            if not bypass:
                g['U']+=np.outer(da,previous);carry=.5*adjoint+p['U'].T@da
        if len(u) and not bypass:du[-1]+=carry
    carry=np.zeros(hidden)
    for j in range(len(out['query_trace'])-1,-1,-1):
        x,previous,activation=out['query_trace'][j];adjoint=du[j]+(carry if not bypass else 0)
        da=(1 if bypass else .5)*adjoint*(1-activation*activation)
        g['W']+=np.outer(da,x);g['b']+=da
        if not bypass:g['U']+=np.outer(da,previous);carry=.5*adjoint+p['U'].T@da
    if bypass and fixed_bypass_gradient:
        for key in ('W','U','b','A','V'):g[key].fill(0)
    return dict(loss=gate+span_loss,gate_loss=gate,span_loss=span_loss,gradient=g,**out)

def finite_difference(p,query,documents,spans,gold,coordinates,bypass=False,epsilon=1e-6):
    result=[]
    for key,index in coordinates:
        old=float(p[key][index]);loss=[]
        for sign in (-1,1):
            p[key][index]=old+sign*epsilon
            loss.append(objective_and_gradient(p,query,documents,spans,gold,bypass,fixed_bypass_gradient=False)['loss'])
        p[key][index]=old;result.append((key,index,(loss[1]-loss[0])/(2*epsilon)))
    return result

def selfcheck():
    rng=np.random.default_rng(7641);h=4;d=6
    p={'W':rng.normal(0,.2,(h,d+2)),'U':rng.normal(0,.15,(h,h)),'b':rng.normal(0,.1,h),'span':rng.normal(0,.2,(3,h)),'stop':rng.normal(0,.2,h),'stop_bias':np.array([.1]),'A':rng.normal(0,.2,(h,h)),'V':rng.normal(0,.2,(h,h))}
    query=rng.normal(0,.4,(3,d));docs=[rng.normal(0,.4,(3,d)),rng.normal(0,.4,(8,d))];spans=all_spans(docs)
    coordinates=[(key,index) for key,value in p.items() for index in np.ndindex(value.shape)];errors=[]
    for bypass in (False,True):
        for gold in (None,(0,7)):
            want=objective_and_gradient(p,query,docs,spans,gold,bypass,fixed_bypass_gradient=False)
            for key,index,fd in finite_difference(p,query,docs,spans,gold,coordinates,bypass):
                error=abs(fd-want['gradient'][key][index]);errors.append(error);assert error<2e-7,(bypass,gold,key,index,error)
    empty=objective_and_gradient(p,np.zeros((0,d)),docs,spans,None)
    assert not empty['gradient']['A'].any() and not empty['gradient']['V'].any()
    return dict(status='passed',coordinates_per_objective=len(coordinates),objectives=4,max_abs_finite_difference_error=max(errors),unequal_windows=[3,8],empty_query_alignment_gradient_zero=True,script_sha256=sha256(Path(__file__).read_bytes()).hexdigest())

if __name__=='__main__':print(json.dumps(selfcheck(),indent=2))
